window.futvizVista("centros-vs-xa","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"centros-vs-xa\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"centros-vs-xa\"]={\"id\":\"centros-vs-xa\",\"titulo\":\"Centros vs. xA\",\"bajada\":\"A la derecha, quien m\u00e1s centra por 90'; arriba, quien m\u00e1s peligro crea (xA). Centrar mucho no es crear mucho.\",\"pregunta\":\"\u00bfCentrar mucho sirve para crear peligro?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"crosses90\",\"label\":\"Centros por 90'\",\"corto\":\"Centros\",\"dec\":2},\"y\":{\"col\":\"xA90\",\"label\":\"xA por 90'\",\"corto\":\"xA90\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\"},\"requiere\":[\"crosses90\",\"xA90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"dist\",\"etiqueta\":\"M\u00e1s at\u00edpicos\",\"ayuda\":\"Los que m\u00e1s se alejan del grupo, para bien o para mal\"},{\"id\":\"x\",\"etiqueta\":\"Centros\",\"ayuda\":\"Ordenados por Centros por 90'\"},{\"id\":\"y\",\"etiqueta\":\"xA90\",\"ayuda\":\"Ordenados por xA por 90'\"}],\"queMirar\":\"La nube sube con el volumen pero con mucha dispersi\u00f3n: abajo a la derecha est\u00e1n los que centran de forma constante con poco peligro (la mayor\u00eda de los centros no encuentra a nadie); arriba, los que generan ocasi\u00f3n por otras v\u00edas adem\u00e1s del centro. Casi todo lo de la derecha son laterales y extremos, as\u00ed que conviene filtrar por posici\u00f3n.\",\"porQue\":\"Los **centros** vienen de FBref (que sigue public\u00e1ndolos) y el **xA** de Understat, as\u00ed que son dos fuentes independientes midiendo cosas cercanas. Correlacionan 0.61: se pisan bastante. El centro es una de las formas de crear ocasi\u00f3n, y hay otras.\\n\\nUn centro cuenta igual salga bien o mal, y el xA solo cuenta los pases que terminaron en tiro; por eso un jugador puede estar muy a la derecha y bajo en el eje vertical sin que eso diga que centra mal \u2014 la diferencia es cu\u00e1nto de su volumen encuentra rematador.\",\"insight\":\"centros\",\"fuente\":\"Understat y FBref\",\"colorPor\":[\"liga\"]};</script>");